const C = { navy:'#173C36', blue:'#087F75', blueLight:'#E5F4F0', bg:'#F5F8F7', card:'#FFFFFF', text:'#182F2A', muted:'#71827E', line:'#E3ECE9', green:'#16845E', greenBg:'#E6F5ED', red:'#D95D58', redBg:'#FDEDEA', purple:'#7163C7', orange:'#E58D3D' };
const initialTransactions = [
 {id:'1',title:'Monthly salary',category:'Income',date:'2026-10-28',amount:42000,type:'income',note:'Salary credited'},
 {id:'2',title:'Grocery shopping',category:'Food',date:'2026-10-27',amount:1850,type:'expense',note:'Weekly groceries'},
 {id:'3',title:'Internet bill',category:'Bills',date:'2026-10-26',amount:899,type:'expense',note:'Wi-Fi bill'},
 {id:'4',title:'Bus pass',category:'Transport',date:'2026-10-25',amount:650,type:'expense',note:'Monthly pass'},
 {id:'5',title:'Freelance work',category:'Income',date:'2026-10-23',amount:5500,type:'income',note:'Design work'},
 {id:'6',title:'Coffee & snacks',category:'Food',date:'2026-10-22',amount:320,type:'expense',note:'Cafe'},
 {id:'7',title:'Electricity',category:'Bills',date:'2026-10-19',amount:1240,type:'expense',note:'Electricity bill'},
 {id:'8',title:'Movie night',category:'Entertainment',date:'2026-10-16',amount:780,type:'expense',note:'Weekend'},
];
const Store = createContext(null);
const useStore = () => useContext(Store);
const useMoney = () => { const {currency}=useStore(); return amount=>money(amount,currency); };
const currencyOptions = {INR:{locale:'en-IN',rate:1},USD:{locale:'en-US',rate:1/83},CNY:{locale:'zh-CN',rate:1/11.5},JPY:{locale:'ja-JP',rate:1/0.56}};
const currencySymbols = {INR:'₹',USD:'$',CNY:'¥',JPY:'¥'};
const toINR = (amount,currency) => Number(amount || 0)/currencyOptions[currency].rate;
const money = (amount,currency='INR') => new Intl.NumberFormat(currencyOptions[currency].locale,{style:'currency',currency,maximumFractionDigits:currency==='INR'?0:2}).format(Number(amount||0)*currencyOptions[currency].rate);
const sum = (arr, type) => arr.filter(x=>!type || x.type===type).reduce((a,x)=>a+Number(x.amount),0);
const dateKey = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const parseDateKey = value => { const [year,month,day]=value.split('-').map(Number);return new Date(year,month-1,day); };
const weekStartKey = (date = new Date()) => { const start = new Date(date); start.setDate(start.getDate()-((start.getDay()+6)%7)); return dateKey(start); };
const periodMatches = (value, period, now = new Date()) => period==='Day' ? value===dateKey(now) : period==='Week' ? value>=weekStartKey(now)&&value<=dateKey(now) : value.slice(0,7)===dateKey(now).slice(0,7);

function AppProvider({children}) {
 const [role,setRole] = useState('Customer');
 const [user,setUser] = useState({name:'Samyu',email:'samyu@example.com',phone:'9876543210'});
 const [transactions,setTransactions] = useState(initialTransactions);
 const [budget,setBudget] = useState(25000);
 const [theme,setTheme] = useState('light');
 const [currency,setCurrency] = useState('INR');
 const addTransaction = tx => { const stored={...tx,amount:toINR(tx.amount,currency),id:String(Date.now())};setTransactions(old=>[stored,...old]);Alert.alert('Transaction updated',`${tx.type==='income'?'Income':'Expense'} of ${money(stored.amount,currency)} added successfully.`); };
 const updateTransaction = tx => { const stored={...tx,amount:toINR(tx.amount,currency)};setTransactions(old=>[stored,...old.filter(x=>x.id!==tx.id)]);Alert.alert('Transaction updated','Your transaction changes have been saved.'); };
 const value = useMemo(()=>({role,setRole,user,setUser,transactions,addTransaction,updateTransaction,budget,setBudget,theme,setTheme,currency,setCurrency}),[role,user,transactions,budget,theme,currency]);
 return <Store.Provider value={value}>{children}</Store.Provider>;
}

function Text({style,...props}) { const {theme}=useStore();const flat=StyleSheet.flatten(style)||{};const mapped=theme==='dark'?({[C.navy]:'#F1F7F5',[C.text]:'#EDF5F2',[C.muted]:'#A5B8B2',[C.blue]:'#55D5C2',[C.green]:'#5ED6A0',[C.red]:'#FF8C82',[C.purple]:'#B7AEFF',[C.orange]:'#FFC078'}[flat.color]||(!flat.color?'#EDF5F2':flat.color)):undefined;return <NativeText {...props} style={[style,mapped?{color:mapped}:null]}/>; }
function Label({children, style}) { return <Text style={[styles.label,style]}>{children}</Text>; }
function Button({title,onPress,secondary=false,style,small=false,icon}) { const {theme}=useStore();const dark=theme==='dark';return <TouchableOpacity activeOpacity={0.82} onPress={onPress} style={[styles.button,{backgroundColor:C.blue,borderRadius:15,shadowColor:C.navy,shadowOpacity:0.14,shadowRadius:9,shadowOffset:{width:0,height:4},elevation:3,flexDirection:'row',gap:8},secondary&&{backgroundColor:dark?'#1B342F':C.card,borderColor:dark?'#34524A':C.line,borderWidth:1,shadowOpacity:0,elevation:0},small&&{minHeight:40,borderRadius:12},style]}>{icon?<Ionicons name={icon} size={18} color={secondary?(dark?'#55D5C2':C.blue):'#FFFFFF'}/>:null}<Text style={[styles.buttonText,secondary&&styles.buttonSecondaryText,small&&styles.buttonSmallText]}>{title}</Text></TouchableOpacity>; }
function Card({children,style}) { const {theme}=useStore();const dark=theme==='dark';return <View style={[styles.card,{backgroundColor:dark?'#19342F':C.card,borderColor:dark?'#2B4941':C.line,borderWidth:1,borderRadius:18,shadowColor:'#071712',shadowOpacity:dark?0.2:0.055,shadowRadius:12,shadowOffset:{width:0,height:5},elevation:2},style]}>{children}</View>; }
function SectionTitle({title,action,onAction}) { return <View style={styles.sectionHead}><Text style={styles.sectionTitle}>{title}</Text>{action?<TouchableOpacity onPress={onAction} activeOpacity={0.7} style={{flexDirection:'row',alignItems:'center',gap:2}}><Text style={styles.link}>{action}</Text><Ionicons name="chevron-forward" size={14} color={C.blue}/></TouchableOpacity>:null}</View>; }
function Screen({children,scroll=true,safeTop=false,centered=false}) { const insets=useSafeAreaInsets();const {theme}=useStore();return <View style={[styles.screen,{backgroundColor:theme==='dark'?'#10241F':C.bg,paddingTop:safeTop?insets.top:0,paddingBottom:0}]}>{scroll?<ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={[styles.content,{paddingBottom:Math.max(28,insets.bottom+16),flexGrow:centered?1:0,justifyContent:centered?'center':'flex-start'}]}>{children}</ScrollView>:children}</View>; }
function Field({label,value,onChangeText,placeholder,keyboardType='default',secureTextEntry=false,multiline=false,labelStyle,inputStyle}) { const {theme,currency}=useStore();const dark=theme==='dark';const visibleLabel=label==='Amount (₹)'?`Amount (${currencySymbols[currency]})`:label;return <View style={styles.fieldWrap}><Label style={labelStyle}>{visibleLabel}</Label><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder||visibleLabel} placeholderTextColor={dark?'#91A59E':'#A1A9B8'} keyboardType={keyboardType} secureTextEntry={secureTextEntry} multiline={multiline} style={[styles.input,{backgroundColor:dark?'#10241F':'#FFFFFF',borderColor:dark?'#34524A':C.line,color:dark?'#EDF5F2':C.text},multiline&&{height:86,textAlignVertical:'top'},inputStyle]} /></View>; }
function Pill({text,active,onPress}) { const {theme}=useStore();return <TouchableOpacity onPress={onPress} style={[styles.pill,active&&styles.pillActive,theme==='dark'&&{backgroundColor:active?'#214A41':'#19342F',borderColor:'#34524A'}]}><Text style={[styles.pillText,active&&styles.pillTextActive]}>{text}</Text></TouchableOpacity>; }

