 return <Screen safeTop><View style={styles.welcomeTop}><View style={styles.logoMark}><Ionicons name="wallet-outline" size={29} color="#FFFFFF"/></View><Text style={styles.brand}>MoneyMate</Text><Text style={styles.tagline}>Your money. Your plan. Your future.</Text><View style={{alignSelf:'stretch',flexDirection:'row',alignItems:'center',gap:12,marginTop:18,padding:14,borderRadius:16,backgroundColor:dark?'#19342F':'#E8F4F0',borderWidth:1,borderColor:dark?'#2B4941':'#D5E8E1'}}><Ionicons name="leaf-outline" size={22} color={dark?'#55D5C2':C.green}/><View style={{flex:1}}><Text style={{fontSize:10,fontWeight:'800',color:dark?'#55D5C2':C.green}}>A MONEY NOTE</Text><Text style={{fontSize:13,fontWeight:'600',lineHeight:19,color:dark?'#EDF5F2':C.text,marginTop:3}}>Small, steady savings can make tomorrow easier.</Text></View></View></View>
 <Label style={{marginTop:22}}>CONTINUE AS</Label><View style={styles.roleRow}><TouchableOpacity onPress={()=>setRolePick('Customer')} style={[styles.roleCard,{backgroundColor:dark?'#19342F':C.card,borderColor:dark?'#34524A':C.line},rolePick==='Customer'&&styles.roleCardSelected,rolePick==='Customer'&&{backgroundColor:dark?'#214A41':C.blueLight}]}><Ionicons name="person-circle-outline" size={27} color={C.blue}/><Text style={styles.roleTitle}>Customer</Text><Text style={styles.roleCaption}>Manage my money</Text></TouchableOpacity><TouchableOpacity onPress={()=>setRolePick('Admin')} style={[styles.roleCard,{backgroundColor:dark?'#19342F':C.card,borderColor:dark?'#34524A':C.line},rolePick==='Admin'&&styles.roleCardSelected,rolePick==='Admin'&&{backgroundColor:dark?'#214A41':C.blueLight}]}><Ionicons name="shield-checkmark-outline" size={27} color={C.purple}/><Text style={styles.roleTitle}>Admin</Text><Text style={styles.roleCaption}>View app insights</Text></TouchableOpacity></View>
 <Button title="Sign in" onPress={()=>{setRole(rolePick);navigation.navigate('SignIn',{role:rolePick});}} style={{marginTop:20}}/><Button title="Create a new account" secondary onPress={()=>{setRole(rolePick);navigation.navigate('SignUp',{role:rolePick});}} style={{marginTop:10}}/></Screen>;
