function SignInScreen({navigation,route}) {
 const {setRole,user}=useStore(); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const role=route.params?.role||'Customer';
 const go=()=>{if(!email.trim()||!email.includes('@'))return Alert.alert('Check email','Enter a valid email address.');if(password.length<4)return Alert.alert('Check password','Password must contain at least 4 characters.');setRole(role);navigation.reset({index:0,routes:[{name:'MainDrawer'}]});Alert.alert('Welcome back',`Signed in as ${role}.`);};
 return <Screen safeTop centered><Text style={[styles.pageTitle,{marginTop:8,textAlign:'center',alignSelf:'center'}]}>Sign in</Text><Text style={[styles.pageSub,{textAlign:'center',alignSelf:'center'}]}>Welcome back, {user.name}.</Text><Card style={{marginTop:24}}><Field label="Email address" value={email} onChangeText={setEmail} placeholder="you@example.com" keyboardType="email-address" labelStyle={{fontSize:14,letterSpacing:0}} inputStyle={{fontSize:18,minHeight:58}}/><Field label="Password" value={password} onChangeText={setPassword} placeholder="Enter password" secureTextEntry labelStyle={{fontSize:14,letterSpacing:0}} inputStyle={{fontSize:18,minHeight:58}}/><Button title="Sign in" onPress={go} style={{marginTop:8}}/><Text style={styles.centerLine}>New to MoneyMate? <Text style={styles.link} onPress={()=>navigation.navigate('SignUp',{role})}>Create account</Text></Text></Card><Button title="Back to home" secondary onPress={()=>navigation.navigate('Welcome')} style={{marginTop:18}}/></Screen>;
}
function SignUpScreen({navigation,route}) {
 const {setRole,setUser}=useStore(); const role=route.params?.role||'Customer'; const [name,setName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');
 const go=()=>{if(name.trim().length<2)return Alert.alert('Name required','Enter your full name.');if(!email.includes('@'))return Alert.alert('Invalid email','Enter a valid email address.');if(password.length<4)return Alert.alert('Weak password','Use at least 4 characters for this demo.');setUser({name:name.trim(),email:email.trim(),phone:'Not added'});setRole(role);Alert.alert('Account created','Your demo profile is ready.');navigation.reset({index:0,routes:[{name:'MainDrawer'}]});};
 return <Screen safeTop><Text style={styles.eyebrow}>GET STARTED</Text><Text style={styles.pageTitle}>Create your{ '\n'}MoneyMate account</Text><Text style={styles.pageSub}>A little clarity today can change tomorrow.</Text><Card style={{marginTop:22}}><Field label="Full name" value={name} onChangeText={setName} placeholder="Your name"/><Field label="Email address" value={email} onChangeText={setEmail} placeholder="you@example.com" keyboardType="email-address"/><Field label="Password" value={password} onChangeText={setPassword} placeholder="At least 4 characters" secureTextEntry/><Button title={`Create ${role} account`} onPress={go} style={{marginTop:8}}/></Card><Button title="Already have an account? Sign in" secondary onPress={()=>navigation.navigate('SignIn',{role})} style={{marginTop:16}}/></Screen>;
}

function MiniBar({label,value,max,color=C.blue,amount}) { const formatMoney=useMoney();const pct=Math.max(4,Math.min(100,max?value/max*100:0));return <View style={{marginTop:13}}><View style={styles.barLabelRow}><Text style={styles.bodyText}>{label}</Text><Text style={styles.barAmount}>{amount||formatMoney(value)}</Text></View><View style={styles.barTrack}><View style={[styles.barFill,{width:`${pct}%`,backgroundColor:color}]}/></View></View>; }
function TransactionRow({item,onPress}) { const formatMoney=useMoney();const icon=item.type==='income'?'arrow-down-outline':item.category==='Food'?'fast-food-outline':item.category==='Transport'?'bus-outline':item.category==='Bills'?'flash-outline':item.category==='Entertainment'?'film-outline':'bag-handle-outline';const tint=item.type==='income'?C.green:item.category==='Food'?C.orange:item.category==='Transport'?C.blue:item.category==='Bills'?C.purple:C.red;return <TouchableOpacity onPress={onPress} activeOpacity={0.8} style={styles.txRow}><View style={[styles.txIcon,{backgroundColor:item.type==='income'?C.greenBg:item.category==='Food'?'#FFF1E4':item.category==='Transport'?'#E7F2F8':item.category==='Bills'?'#F0EDFA':'#FDEDEA'}]}><Ionicons name={icon} size={20} color={tint}/></View><View style={{flex:1}}><Text style={styles.txTitle}>{item.title}</Text><Text style={styles.txMeta}>{item.category} · {item.date}</Text></View><Text style={[styles.txAmount,{color:item.type==='income'?C.green:C.text}]}>{item.type==='income'?'+':'−'}{formatMoney(item.amount)}</Text></TouchableOpacity>; }
function HomeScreen({navigation}) {
 const {transactions,role,user,budget,theme}=useStore();const formatMoney=useMoney();const income=sum(transactions,'income'),expense=sum(transactions,'expense'),balance=income-expense;
 const today=dateKey(),weekStart=weekStartKey();const reports=[{name:'Daily',sub:'Today',val:sum(transactions.filter(t=>t.date===today),'expense')},{name:'Weekly',sub:'This week',val:sum(transactions.filter(t=>t.date>=weekStart&&t.date<=today),'expense')},{name:'Monthly',sub:new Date().toLocaleString('en-IN',{month:'long'}),val:sum(transactions.filter(t=>t.date.slice(0,7)===today.slice(0,7)),'expense')}];
 return <Screen><View style={styles.topRow}><View><Text style={styles.hello}>Good morning, {user.name}</Text><Text style={styles.pageSubSmall}>Here’s your money snapshot.</Text></View><View style={[styles.avatar,{backgroundColor:'#D6ECE5'}]}><Text style={styles.avatarText}>{(user.name||'B').slice(0,1).toUpperCase()}</Text></View></View>
 <View style={styles.balanceCard}><View style={styles.balanceTop}><Text style={styles.balanceLabel}>TOTAL BALANCE</Text><View style={styles.balanceTag}><Ionicons name="checkmark-circle" size={14} color={C.green}/><Text style={styles.balanceTagText}>On track</Text></View></View><Text style={styles.balanceAmount}>{formatMoney(balance)}</Text><Text style={styles.balanceCaption}>Your available balance</Text><View style={styles.balanceStats}><View style={{flex:1}}><View style={{flexDirection:'row',alignItems:'center',gap:5}}><Ionicons name="arrow-down-circle-outline" size={15} color="#BCE8D2"/><Text style={styles.balanceSmallLabel}>Income</Text></View><Text style={styles.balanceSmallValue}>{formatMoney(income)}</Text></View><View style={styles.balanceStatLine}/><View style={{flex:1}}><View style={{flexDirection:'row',alignItems:'center',gap:5}}><Ionicons name="arrow-up-circle-outline" size={15} color="#FFC3B8"/><Text style={styles.balanceSmallLabel}>Expenses</Text></View><Text style={styles.balanceSmallValue}>{formatMoney(expense)}</Text></View></View></View>
 <View style={styles.quickRow}><TouchableOpacity onPress={()=>navigation.navigate('AddTransaction')} style={styles.quickAction}><View style={[styles.quickIcon,{backgroundColor:C.blueLight}]}><Ionicons name="add-outline" size={22} color={C.blue}/></View><Text style={styles.quickLabel}>Add transaction</Text></TouchableOpacity><TouchableOpacity onPress={()=>navigation.navigate('Analysis')} style={styles.quickAction}><View style={[styles.quickIcon,{backgroundColor:C.greenBg}]}><Ionicons name="stats-chart-outline" size={21} color={C.green}/></View><Text style={styles.quickLabel}>View analysis</Text></TouchableOpacity><TouchableOpacity onPress={()=>navigation.navigate('Transactions')} style={styles.quickAction}><View style={[styles.quickIcon,{backgroundColor:'#FFF1E4'}]}><Ionicons name="time-outline" size={22} color={C.orange}/></View><Text style={styles.quickLabel}>History</Text></TouchableOpacity><TouchableOpacity onPress={()=>navigation.navigate('Categories')} style={styles.quickAction}><View style={[styles.quickIcon,{backgroundColor:'#F0EDFA'}]}><Ionicons name="grid-outline" size={21} color={C.purple}/></View><Text style={styles.quickLabel}>Categories</Text></TouchableOpacity></View>
 <SectionTitle title="Spending reports" action="Full analysis" onAction={()=>navigation.navigate('Analysis')}/><View style={styles.reportRow}>{reports.map((r,i)=><Card key={r.name} style={[styles.reportCard,{backgroundColor:theme==='dark'?'#19342F':C.card,borderColor:theme==='dark'?'#2B4941':C.line,borderTopWidth:3,borderTopColor:[C.blue,C.purple,C.orange][i]}]}><Text style={styles.reportLabel}>{r.name}</Text><Text style={styles.reportSub}>{r.sub}</Text><Text style={styles.reportValue}>{formatMoney(r.val)}</Text><View style={[styles.reportDot,{backgroundColor:[C.blue,C.purple,C.orange][i]}]}/></Card>)}</View>
 <Card style={{marginTop:16}}><View style={styles.sectionHead}><Text style={styles.sectionTitle}>Monthly budget</Text><Text style={styles.barAmount}>{formatMoney(expense)} / {formatMoney(budget)}</Text></View><MiniBar label="Budget used" value={expense} max={budget} color={expense>budget?C.red:C.blue} amount={`${Math.min(100,Math.round(expense/budget*100))}%`}/><Text style={[styles.helperText,{marginTop:9}]}>{expense>budget?'You have crossed your planned budget. Review your expenses.':`${formatMoney(Math.max(0,budget-expense))} left in your planned budget.`}</Text></Card>
 <SectionTitle title="Recent transactions" action="See all" onAction={()=>navigation.navigate('Transactions')}/><Card style={{paddingVertical:4}}>{transactions.slice(0,4).map(t=><TransactionRow key={t.id} item={t} onPress={()=>navigation.navigate('TransactionDetail',{transaction:t})}/>)}</Card></Screen>;
}
